  wire [2:0] req_o;
  wire N0,N1;
  assign req_o[0] = target_cord_i == my_cord_i;
  assign req_o[1] = target_cord_i < my_cord_i;
  assign req_o[2] = N0 & N1;
  assign N0 = ~req_o[0];
  assign N1 = ~req_o[1];

endmodule



module bsg_counter_set_down_4_1
(
  clk_i,
  reset_i,
  set_i,
  val_i,
  down_i,
  count_r_o
);

  input [3:0] val_i;
  output [3:0] count_r_o;
  input clk_i;
  input reset_i;
  input set_i;
  input down_i;
  wire [3:0] count_r_o,ctr_n;
  wire N0,N1,N2,N3,N4,N5,N6,N7,N8,N9,N10,N11,N12,N13,N14,N15,N16,N17,N18;
  reg count_r_o_3_sv2v_reg,count_r_o_2_sv2v_reg,count_r_o_1_sv2v_reg,
  count_r_o_0_sv2v_reg;
  assign count_r_o[3] = count_r_o_3_sv2v_reg;
  assign count_r_o[2] = count_r_o_2_sv2v_reg;
  assign count_r_o[1] = count_r_o_1_sv2v_reg;
  assign count_r_o[0] = count_r_o_0_sv2v_reg;

  always @(posedge clk_i) begin
    if(N18) begin
      count_r_o_3_sv2v_reg <= N7;
    end 
  end


  always @(posedge clk_i) begin
    if(N18) begin
      count_r_o_2_sv2v_reg <= N6;
    end 
  end


  always @(posedge clk_i) begin
    if(N18) begin
      count_r_o_1_sv2v_reg <= N5;
    end 
  end


  always @(posedge clk_i) begin
    if(N18) begin
      count_r_o_0_sv2v_reg <= N4;
    end 
  end

  assign { N14, N13, N12, N11 } = count_r_o - 1'b1;
  assign { N7, N6, N5, N4 } = (N0)? { 1'b0, 1'b0, 1'b0, 1'b0 } : 
                              (N1)? ctr_n : 1'b0;
  assign N0 = reset_i;
  assign N1 = N3;
  assign ctr_n = (N2)? val_i : 
                 (N16)? { N14, N13, N12, N11 } : 1'b0;
  assign N2 = set_i;
  assign N3 = ~reset_i;
  assign N8 = down_i | set_i;
  assign N9 = ~N8;
  assign N10 = N16;
  assign N15 = ~set_i;
  assign N16 = down_i & N15;
  assign N17 = N9 & N3;
  assign N18 = ~N17;

endmodule



module bsg_wormhole_router_input_control_3_4
(
  clk_i,
  reset_i,
  fifo_v_i,
  fifo_decoded_dest_i,
  fifo_payload_len_i,
  fifo_yumi_i,
  reqs_o,
  release_o,
  detected_header_o
);

  input [2:0] fifo_decoded_dest_i;
  input [3:0] fifo_payload_len_i;
  output [2:0] reqs_o;
  input clk_i;
  input reset_i;
  input fifo_v_i;
  input fifo_yumi_i;
  output release_o;
  output detected_header_o;
  wire [2:0] reqs_o;
  wire release_o,detected_header_o,N0,N1,_0_net_,_1_net_,N2,N3,N4,N5,N6;
  wire [3:0] payload_ctr_r;

  bsg_counter_set_down_4_1
  ctr
  (
    .clk_i(clk_i),
    .reset_i(reset_i),
    .set_i(_0_net_),
    .val_i(fifo_payload_len_i),
    .down_i(_1_net_),
    .count_r_o(payload_ctr_r)
  );

  assign reqs_o = (N0)? fifo_decoded_dest_i : 
                  (N1)? { 1'b0, 1'b0, 1'b0 } : 1'b0;
  assign N0 = detected_header_o;
  assign N1 = N2;
  assign release_o = ~N5;
  assign N5 = N4 | payload_ctr_r[0];
  assign N4 = N3 | payload_ctr_r[1];
  assign N3 = payload_ctr_r[3] | payload_ctr_r[2];
  assign detected_header_o = release_o & fifo_v_i;
  assign _1_net_ = fifo_yumi_i & N6;
  assign N6 = ~release_o;
  assign _0_net_ = fifo_yumi_i & release_o;
  assign N2 = ~detected_header_o;

endmodule



