  clk_i,
  reset_i,
  fifo_v_i,
  fifo_decoded_dest_i,
  fifo_payload_len_i,
  fifo_yumi_i,
  reqs_o,
  release_o,
  detected_header_o
);

  input [1:0] fifo_decoded_dest_i;
  input [3:0] fifo_payload_len_i;
  output [1:0] reqs_o;
