  input reset_i;
  input fifo_v_i;
  input fifo_yumi_i;
  output release_o;
  output detected_header_o;
  wire [1:0] reqs_o;
  wire release_o,detected_header_o,N0,N1,_0_net_,_1_net_,N2,N3,N4,N5,N6;
  wire [3:0] payload_ctr_r;

  bsg_counter_set_down_4_1
  ctr
  (
    .clk_i(clk_i),
    .reset_i(reset_i),
    .set_i(_0_net_),
    .val_i(fifo_payload_len_i),
    .down_i(_1_net_),
    .count_r_o(payload_ctr_r)
  );

  assign reqs_o = (N0)? fifo_decoded_dest_i : 
                  (N1)? { 1'b0, 1'b0 } : 1'b0;
  assign N0 = detected_header_o;
  assign N1 = N2;
